mapper.delete:
delete from t_std_metemodel_detail
        where model_id = #{modelId, jdbcType=BIGINT}
        and mete_id=#{meteId,jdbcType=BIGINT}

mapper.select:
select
a.model_id,
a.mete_id,
a.custom_type,
b.dict_note AS "customTypeName",
a.mete_code,
a.mete_name,
a.mete_type,
a.unit,
a.alarm_note,
a.alarm_explain,
a.alarm_type,
a.up_effect,
a.low_effect,
a.alarm_level,
a.high_limit1,
a.low_limit1,
a.high_limit2,
a.low_limit2,
a.high_limit3,
a.low_limit3,
a.high_limit4,
a.low_limit4,
a.alarm_delay,
a.alarm_cnt,
a.threshold_abs,
a.threshold_per,
a.modulus
from t_std_metemodel_detail a
left join t_dict_business b ON a.custom_type = b.dict_code
where 1 = 1
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.mete_id = #{meteId, jdbcType=BIGINT}
 and a.custom_type = #{customType, jdbcType=INTEGER}
 and b.dict_note = #{customTypeName, jdbcType=VARCHAR}
 and a.mete_code = #{meteCode, jdbcType=VARCHAR}
 and a.mete_name = #{meteName, jdbcType=VARCHAR}
 and a.mete_type = #{meteType, jdbcType=VARCHAR}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.alarm_note = #{alarmNote, jdbcType=VARCHAR}
 and a.alarm_explain = #{alarmExplain, jdbcType=VARCHAR}
 and a.alarm_type = #{alarmType, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=REAL}
 and a.low_effect = #{lowEffect, jdbcType=REAL}
 and a.alarm_level = #{alarmLevel, jdbcType=INTEGER}
 and a.high_limit1 = #{highLimit1, jdbcType=REAL}
 and a.low_limit1 = #{lowLimit1, jdbcType=REAL}
 and a.high_limit2 = #{highLimit2, jdbcType=REAL}
 and a.low_limit2 = #{lowLimit2, jdbcType=REAL}
 and a.high_limit3 = #{highLimit3, jdbcType=REAL}
 and a.low_limit3 = #{lowLimit3, jdbcType=REAL}
 and a.high_limit4 = #{highLimit4, jdbcType=REAL}
 and a.low_limit4 = #{lowLimit4, jdbcType=REAL}
 and a.alarm_delay = #{alarmDelay, jdbcType=INTEGER}
 and a.alarm_cnt = #{alarmCnt, jdbcType=INTEGER}
 and a.threshold_abs = #{thresholdAbs, jdbcType=NUMERIC}
 and a.threshold_per = #{thresholdPer, jdbcType=NUMERIC}
 and a.modulus = #{modulus, jdbcType=INTEGER}

SELECT
a.model_id,
a.mete_id,
a.custom_type,
b.dict_note AS "customTypeName",
c.dict_note AS "meteTypeName",
d.device_type AS "deviceType",
e.dict_note AS "deviceTypeName",
a.mete_code,
a.mete_name,
a.mete_type,
a.unit,
a.alarm_note,
a.alarm_explain,
a.alarm_type,
a.up_effect,
a.low_effect,
a.alarm_level,
a.high_limit1,
a.low_limit1,
a.high_limit2,
a.low_limit2,
a.high_limit3,
a.low_limit3,
a.high_limit4,
a.low_limit4,
a.alarm_delay,
a.alarm_cnt,
a.threshold_abs,
a.threshold_per,
a.modulus
FROM
(
(
t_std_metemodel_detail a
LEFT JOIN t_dict_business b ON a.custom_type = b.dict_code
AND b.col_name = "custom_type"
)
LEFT JOIN t_dict_business c ON a.mete_type = c.dict_code
AND c.col_name = "mete_kind"
)
LEFT JOIN (
t_std_metemodel d
LEFT JOIN t_dict_business e ON d.device_type = e.dict_code
AND e.col_name = "device_type"
) ON a.model_id = d.model_id
where 1=1
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.mete_id = #{meteId, jdbcType=BIGINT}
 and a.custom_type = #{customType, jdbcType=INTEGER}
 and b.dict_note = #{customTypeName, jdbcType=VARCHAR}
 and c.dict_note = #{meteTypeName, jdbcType=VARCHAR}
 and d.device_type = #{deviceType, jdbcType=INTEGER}
 and e.dict_note = #{deviceTypeName, jdbcType=VARCHAR}
 and a.mete_code = #{meteCode, jdbcType=VARCHAR}
 and a.mete_name LIKE CONCAT ('%',#{meteName, jdbcType=VARCHAR},'%')
 and a.mete_type = #{meteType, jdbcType=VARCHAR}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.alarm_note = #{alarmNote, jdbcType=VARCHAR}
 and a.alarm_explain = #{alarmExplain, jdbcType=VARCHAR}
 and a.alarm_type = #{alarmType, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=REAL}
 and a.low_effect = #{lowEffect, jdbcType=REAL}
 and a.alarm_level = #{alarmLevel, jdbcType=INTEGER}
 and a.high_limit1 = #{highLimit1, jdbcType=REAL}
 and a.low_limit1 = #{lowLimit1, jdbcType=REAL}
 and a.high_limit2 = #{highLimit2, jdbcType=REAL}
 and a.low_limit2 = #{lowLimit2, jdbcType=REAL}
 and a.high_limit3 = #{highLimit3, jdbcType=REAL}
 and a.low_limit3 = #{lowLimit3, jdbcType=REAL}
 and a.high_limit4 = #{highLimit4, jdbcType=REAL}
 and a.low_limit4 = #{lowLimit4, jdbcType=REAL}
 and a.alarm_delay = #{alarmDelay, jdbcType=INTEGER}
 and a.alarm_cnt = #{alarmCnt, jdbcType=INTEGER}
 and a.threshold_abs = #{thresholdAbs, jdbcType=NUMERIC}
 and a.threshold_per = #{thresholdPer, jdbcType=NUMERIC}
 and a.modulus = #{modulus, jdbcType=INTEGER}
